,"input_types":"2950 2950 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"309644","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"cd1bbef02893b4ccee1c8690a18204ae","returns":"boolean","body_md5":"c5bccecda692a98c7e21f29d15ea9b1d","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_encounter"],"signature":"mission_factory_owner.c444_peaceful_history_complete_v1(uuid, uuid)","volatility":"s","input_types":"2950 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","oid":"31338","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"877b7860e80d4d9b8e5bae16cfea888f","returns":"jsonb","body_md5":"c742683c050a8fb6e23c01635d5b0ad0","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_mode","p_reason","p_expected_control_version","p_request_key"],"signature":"public.master_v2_suspend(uuid, text, text, bigint, uuid)","volatility":"v","input_types":"2950 25 25 20 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","oid":"31339","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"6429cdee72bd7f6459adaaa9ad744efb","returns":"jsonb","body_md5":"f93081b87c166d9aca2b76b18ce85653","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_expected_control_version","p_request_key"],"signature":"public.master_v2_resume(uuid, bigint, uuid)","volatility":"v","input_types":"2950 20 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","oid":"47914","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"e880037a61a