 IF live->>'R37md5' IS DISTINCT FROM '87c42ce779f3fe8844bf39fad346fdad' OR ((WITH targets(label,character_id) AS (VALUES ('pg_tamako','f335b077-34a1-41c3-94aa-58ec674b649b'::uuid),('master_riuji','6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)), resources AS (select t.label,c.rank,c.vita,c.vita_max,c.chakra,c.chakra_max,c.exp,c.xp_lifetime,c.money,c.pool_concesso,c.unspent_points,md5(jsonb_build_array(c.taijutsu,c.ninjutsu,c.genjutsu,c.forza,c.velocita,c.mente,c.resistenza,c.fuuinjutsu,c.kekkei_genkai,c.lealta,c.via,c.fama,c.slot_extra)::text) stats_md5,(select count(*) from public.character_inventory x where x.character_id=c.id) inventory_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.item_id,x.quantity,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_inventory x where x.character_id=c.id) inventory_md5,(select count(*) from public.lesson_progress x where x.user_id=c.user_id) lesson_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.lesson_id,x.completed_at) order by x.id),'[]'::jsonb)::text) from public.lesson_progress x where x.user_id=c.user_id) lesson_md5,(select count(*) from public.character_jutsu x where x.user_id=c.user_id) jutsu_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.jutsu_id,x.source,x.learned_at) order by x.id),'[]'::jsonb)::text) from public.character_jutsu x where x.user_id=c.user_id) jutsu_md5,(select count(*) from public.character_abilities x where x.character_id=c.id) ability_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.technique_id,x.state,x.sessions_done,x.started_at,x.activated_at) order by x.id),'[]'::jsonb)::text) from public.character_abilities x where x.character_id=c.id) ability_md5,(select count(*) from public.character_perks x where x.character_id=c.id) perk_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.tipo,x.dettaglio,x.costo,x.grado_tecnica,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_perks x where x.character_id=c.id) perk_md5,(select count(*) from public.esame_prove x where x.candidate_user=c.user_id and x.stato='aperta') legacy_exam_open,(select count(*) from exam_regia_private.bindings x where x.owner_user=c.user_id and x.state<>'closed') legacy_binding_open,md5(jsonb_build_array(c.clan,c.element,c.element2,c.cercoterio,c.sigillo)::text) identity_build_md5 from targets t join public.characters c on c.id=t.character_id order by t.label) select jsonb_build_object('at',clock_timestamp(),'protected_md5',md5(jsonb_agg(to_jsonb(r) order by label)::text),'rows',count(*),'fields_per_pg',(select count(*) from jsonb_object_keys((select to_jsonb(x)-'label' from resources x limit 1)))) from resources r))->>'protected_md5' IS DISTINCT FROM 'd41adde267a202a8ff4c6c194eb0a09f' THEN RAISE EXCEPTION 'HUMAN32_R37_OR_PROTECTED_DRIFT';END IF;
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c444_runtime_control WHERE singleton AND enabled AND expires_at>statement_timestamp()) OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c463_optin_control WHERE singleton AND enabled AND session_ids=ARRAY['97d2a684-956d-57ad-8d84-aca627dd9e5c']::uuid[] AND expires_at>statement_timestamp()) THEN RAISE EXCEPTION 'HUMAN32_FINITE_STAFF_SCOPE_REQUIRED';END IF;
END $guard$;
CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_runtime_state_v1(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q mission_factory_owner.quest_run_sources;m public.master_v2_sessions;r public.mission_run_state;ev public.mission_run_events;hw mission_generic_owner.regia_human_windows_v1;scene jsonb;scope jsonb;ctx jsonb;term jsonb;ds jsonb:='[]'::jsonb;reason text;active boolean;pending boolean;enc boolean;options jsonb:='[]'::jsonb;ascope jsonb;ne mission_factory_owner.quest_episodes;nextdto jsonb;
BEGIN
 PERFORM mission_factory_owner.c407_identity_v1(p_session);PERFORM mission_factory_owner.c444_source_read_assert_v1(p_session);
 SELECT * INTO STRICT q FROM mission_factory_owner.quest_run_sources WHERE session_id=p_session;SELECT * INTO STRICT m FROM public.master_v2_sessions WHERE id=p_session;SELECT * INTO STRICT r FROM public.mission_run_state WHERE master_session_id=p_session;
 SELECT * INTO ev FROM public.mission_run_events WHERE id=r.last_event_id AND master_session_id=p_session;
 SELECT * INTO hw FROM mission_generic_owner.regia_human_windows_v1 WHERE master_session_id=p_session ORDER BY preparation_revision DESC,id DESC LIMIT 1;
 pending:=EXISTS(SELECT 1 FROM public.mission_run_outbox WHERE master_session_id=p_session AND state IN('pending','human_directed'));
 active:=q.state='started' AND m.stato='in_corso' AND m.closed_at IS NULL AND r.run_phase='in_corso';
 reason:=CASE WHEN NOT mission_factory_owner.c444_enabled_v1() OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c407_control WHERE singleton AND admission_enabled AND manual_fato_enabled AND d100_enabled) OR NOT EXISTS(SELECT 1 FROM mission_factory_owner.c412_control WHERE singleton AND runtime_enabled) THEN 'DISABLED' WHEN q.state='terminal' THEN 'TERMINAL' WHEN NOT active THEN 'NOT_ACTIVE' WHEN pending THEN 'FATO_PENDING' ELSE 'READY' END;
 ascope:=mission_factory_owner.c444_action_scope_v1(p_session);
 IF active THEN
  scene:=mission_factory_owner.quest_scene_v1(p_session,r.current_step_key);options:=coalesce(ascope->'decisions','[]'::jsonb);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(options)o WHERE (o->'to_step_key'='null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(scene->'terminal_options','[]'::jsonb))t WHERE t->>'decision_key'=o->>'decision_key' AND t->'to_step_key'='null'::jsonb)) OR (o->'to_step_key'<>'null'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(scene->'triggers','[]'::jsonb))t WHERE t->>'decision_key'=o->>'decision_key'))) THEN RAISE EXCEPTION 'C456_NATIVE_COMPILED_DECISION_SOURCE_DRIFT' USING ERRCODE='40001';END IF;
  IF reason='READY' THEN scope:=public.mission_factory_quest_d100_binding_scope_v1(p_session);END IF;
 END IF;
 IF q.state='terminal' THEN term:=mission_factory_owner.c444_terminal_confirmed_v1(p_session);SELECT * INTO ne FROM mission_factory_owner.quest_episodes WHERE arc_id=q.arc_id AND ordinal=q.episode_ordinal+1;IF ne.id IS NOT NULL THEN nextdto:=jsonb_build_object('quest_episode_id',ne.id,'ordinal',ne.ordinal,'source_sha256',ne.source_sha256,'eligible',mission_factory_owner.c444_enrollment_open_v1(ne.id),'reason_code',CASE WHEN NOT mission_factory_owner.c444_enabled_v1() OR mission_factory_owner.c416_kind_live_v1() IS DISTINCT FROM true THEN 'DISABLED' WHEN mission_factory_owner.c444_enrollment_open_v1(ne.id) THEN 'READY' ELSE 'NATIVE_ENROLLMENT_CLOSED' END);END IF;END IF;
